1	package payflow
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"io"
9		"math"
10		"os"
11		"path/filepath"
12		"sort"
13		"sync"
14	)
15	
16	// 账本磁盘格式（单文件，一个 JSON 文档，末附 sha256 校验和）：
17	//
18	//	{"version":1,
19	//	 "initial_balances":[{"account":"aa","asset":"usdc","balance":1000}],
20	//	 "balances":[{"account":"aa","asset":"usdc","balance":700}],
21	//	 "settlements":[{...一笔成功结算及其当时费率...}],
22	//	 "refunds":[{...一笔成功全额退款...}],
23	//	 "checksum":"<sha256 of the document without checksum>"}
24	//
25	// initial_balances 在初始化时冻结，用于检测任何对历史余额/记录的篡改；
26	// checksum 覆盖截断、比特翻转与所有语义编辑。
27	//
28	// refunds 字段缺省（旧版账本没有该字段）即视为空列表：旧文件可直接打开；
29	// 只要账本没有发生退款，写回时该字段继续缺省，读取旧账本不会改写文件。
30	//
31	// 写入采用“临时文件 + fsync + 原子 rename + 目录 fsync”，
32	// 因此崩溃后磁盘上只会存在完整的旧版本或完整新版本，
33	// 不会出现“扣款/退款无记录”或“记录未改余额”的中间状态。
34	const ledgerVersion = 1
35	
36	// 结算结果状态，与命令行输出一一对应，可分别识别。
37	const (
38		StatusSettled         = "settled"              // 成功扣款
39		StatusDuplicate       = "duplicate"            // 幂等重试：字段与原记录一致，返回原结算/原退款，不再入账
40		StatusConflict        = "conflict"             // 编号冲突：编号已成功但字段或费率/目标或原因不同
41		StatusState           = "state_error"          // 非 pending
42		StatusFunds           = "insufficient_balance" // 余额不足（含不存在的账户/资产组合）
43		StatusLimitExceeded   = "limit_exceeded"       // 本次批次该 (账户, 资产) 组合的扣款上限不足
44		StatusInvalid         = "invalid_parameter"
45		StatusStorage         = "storage_error"
46		StatusRefundSuccess   = "refunded"         // 成功全额退回
47		StatusNotFound        = "not_found"        // 退款目标结算不存在（含原付款只曾失败）
48		StatusAlreadyRefunded = "already_refunded" // 原付款已被其他退款编号全额退回
49	)
50	
51	// 拒绝原因。
52	const (
53		reasonEmptyID         = "intent id must not be empty"
54		reasonEmptyAccount    = "account must not be empty"
55		reasonEmptyAsset      = "asset must not be empty"
56		reasonBadAmount       = "amount must be a positive int64"
57		reasonOverflow        = "amount plus fee overflows int64"
58		reasonNotPending      = "intent is not pending"
59		reasonFunds           = "insufficient balance for amount plus fee"
60		reasonLimitExceeded   = "charge limit exceeded for %s/%s: max_charged %d, used %d, this item charges %d"
61		reasonDuplicate       = "duplicate settlement attempt"
62		reasonConflict        = "settlement id conflicts with a different request"
63		reasonEmptyRefundID   = "refund id must not be empty"
64		reasonEmptySettlement = "settlement_id must not be empty"
65		reasonEmptyReason     = "refund reason must not be empty"
66		reasonSettlementGone  = "settlement %q not found"
67		reasonAlreadyRefunded = "settlement %q has already been refunded by %q"
68		reasonRefundConflict  = "refund id conflicts with a different request"
69		reasonDuplicateRefund = "duplicate refund attempt"
70	)
71	
72	// BalanceInit 是初始化时一个 (账户, 资产) 组合的起始余额。
73	type BalanceInit struct {
74		Account string `json:"account"`
75		Asset   string `json:"asset"`
76		Balance int64  `json:"balance"`
77	}
78	
79	// PaymentIntent 是批次中的一项付款请求。金额使用指针以区分“缺省/null”与 0。
80	type PaymentIntent struct {
81		ID        string `json:"id"`
82		Account   string `json:"account"`
83		Paymaster string `json:"paymaster"`
84		Asset     string `json:"asset"`
85		Amount    *int64 `json:"amount"`
86		Nonce     uint64 `json:"nonce"`
87		State     string `json:"state"`
88	}
89	
90	// ChargeLimit 是本次提交中一个 (账户, 资产) 组合的扣款上限：该组合在本批次内
91	// 成功落账的 charged（付款金额 + 手续费）累计不得超过 max_charged。
92	// 上限仅对本次提交有效，不持久化；历史扣款与退款都不占本次额度。
93	// MaxCharged 使用指针以区分“缺省/null”与显式给出的 0（0 表示禁止该组合新增扣款）。
94	type ChargeLimit struct {
95		Account    string `json:"account"`
96		Asset      string `json:"asset"`
97		MaxCharged *int64 `json:"max_charged"`
98	}
99	
100	// FeeBatch 是一次提交：固定费率（基点）+ 有序意图列表 + 可选的本次扣款上限。
101	// Limits 缺省、为 null 或为空数组时不限制扣款。
102	type FeeBatch struct {
103		FeeBps  int             `json:"fee_bps"`
104		Intents []PaymentIntent `json:"intents"`
105		Limits  []ChargeLimit   `json:"limits,omitempty"`
106	}
107	
108	// Record 是一笔成功结算留下的永久记录，按成功先后顺序保存。
109	type Record struct {
110		ID        string `json:"id"`
111		Account   string `json:"account"`
112		Paymaster string `json:"paymaster"`
113		Asset     string `json:"asset"`
114		Amount    int64  `json:"amount"`
115		Nonce     uint64 `json:"nonce"`
116		FeeBps    int    `json:"fee_bps"`
117		Fee       int64  `json:"fee"`
118		Charged   int64  `json:"charged"`
119		Seq       int64  `json:"seq"`
120	}
121	
122	// ItemResult 是批次中一项的处理结果，顺序与输入逐项对应。
123	type ItemResult struct {
124		ID     string  `json:"id"`
125		Status string  `json:"status"`
126		Reason string  `json:"reason,omitempty"`
127		Record *Record `json:"record,omitempty"`
128	}
129	
130	// BatchResult 是一次提交的结果。空批次对应空 Results。
131	type BatchResult struct {
132		Results []ItemResult `json:"results"`
133	}
134	
135	// PreviewResult 是一次提交预览（--dry-run）的结果。DryRun 恒为 true，
136	// 用于与真实提交输出区分；Results 与输入逐项对应，状态、失败原因与结算
137	// 记录格式与 Submit 完全一致——其中 settled 表示“按当前账本预计能够成功”，
138	// 携带的记录使用从当前最大付款序号之后连续递增的预计序号。
139	// 预览不写入账本，序号、余额与本批次额度都不会被预留。
140	type PreviewResult struct {
141		DryRun  bool         `json:"dry_run"`
142		Results []ItemResult `json:"results"`
143	}
144	
145	// RefundRequest 是退款批次中的一项：退款编号、原付款编号、退款原因，三者均须非空。
146	type RefundRequest struct {
147		ID           string `json:"id"`
148		SettlementID string `json:"settlement_id"`
149		Reason       string `json:"reason"`
150	}
151	
152	// RefundBatch 是一次退款提交：有序的退款请求列表。
153	type RefundBatch struct {
154		Refunds []RefundRequest `json:"refunds"`
155	}
156	
157	// RefundRecord 是一笔成功全额退款留下的永久记录，按退款成功先后顺序保存。
158	// 退款金额与去向（账户/资产/总额）全部由原结算记录确定，因此一并冗余记录，
159	// 使每条退款都能脱离上下文自解释、可追溯原结算。
160	// AfterSeq 是退款落账时结算历史的长度：余额校验要求该结算在此时点之前发生。
161	type RefundRecord struct {
162		ID           string `json:"id"`
163		SettlementID string `json:"settlement_id"`
164		Reason       string `json:"reason"`
165		Account      string `json:"account"`
166		Asset        string `json:"asset"`
167		Amount       int64  `json:"amount"`
168		Fee          int64  `json:"fee"`
169		Charged      int64  `json:"charged"`
170		AfterSeq     int64  `json:"after_seq"`
171		Seq          int64  `json:"seq"`
172	}
173	
174	// RefundResult 是一项退款的处理结果。成功与幂等重复携带原付款编号、账户、
175	// 资产、退款总额与原因；失败只带状态与说明。
176	type RefundResult struct {
177		ID           string        `json:"id"`
178		Status       string        `json:"status"`
179		Reason       string        `json:"reason,omitempty"`
180		SettlementID string        `json:"settlement_id,omitempty"`
181		Account      string        `json:"account,omitempty"`
182		Asset        string        `json:"asset,omitempty"`
183		Charged      int64         `json:"charged,omitempty"`
184		Record       *RefundRecord `json:"record,omitempty"`
185	}
186	
187	// RefundBatchResult 是一次退款提交的结果，顺序与输入逐项对应。
188	type RefundBatchResult struct {
189		Results []RefundResult `json:"results"`
190	}
191	
192	// BalanceView 是一个 (账户, 资产) 组合的当前余额。
193	type BalanceView struct {
194		Account string `json:"account"`
195		Asset   string `json:"asset"`
196		Balance int64  `json:"balance"`
197	}
198	
199	// Snapshot 是账本查询结果。Refunds 按退款成功先后排列，无退款时为空列表。
200	type Snapshot struct {
201		Balances    []BalanceView  `json:"balances"`
202		Settlements []Record       `json:"settlements"`
203		Refunds     []RefundRecord `json:"refunds"`
204	}
205	
206	// LedgerError 携带可机读分类（与 ItemResult.Status 对齐）和说明。
207	type LedgerError struct {
208		Kind    string
209		Message string
210	}
211	
212	func (e *LedgerError) Error() string { return e.Kind + ": " + e.Message }
213	
214	// 错误分类。
215	const (
216		ErrInvalid = "invalid_parameter"
217		ErrExists  = "ledger_exists"
218		ErrCorrupt = "corrupt_ledger"
219		ErrStorage = "storage_error"
220		ErrClosed  = "ledger_closed"
221		ErrNotInit = "ledger_not_initialized"
222	)
223	
224	func ledgerError(kind, format string, args ...any) error {
225		return &LedgerError{Kind: kind, Message: fmt.Sprintf(format, args...)}
226	}
227	
228	// KindOf 返回错误的分类；非账本错误按存储错误处理。
229	func KindOf(err error) string {
230		var le *LedgerError
231		if errors.As(err, &le) {
232			return le.Kind
233		}
234		return ErrStorage
235	}
236	
237	// FailWriter 注入存储故障：返回 true 时本次持久化失败，
238	// 内存状态必须回滚到该项执行之前。仅用于测试。
239	type FailWriter interface {
240		FailNextPersist() bool
241	}
242	
243	type balanceKey struct {
244		account string
245		asset   string
246	}
247	
248	type ledgerState struct {
249		Version     int
250		Initial     map[balanceKey]int64 // 初始化时冻结的起始余额，仅用于完整性校验
251		Balances    map[balanceKey]int64 // 当前余额
252		Settlements []Record
253		Refunds     []RefundRecord
254	}
255	
256	// 磁盘文档字段（顺序即签名时的规范顺序，不得调整，否则旧文件校验失败）。
257	// Refunds 使用 omitempty：旧版账本缺省该字段即可读入为 nil（视为空），
258	// 且无退款的账本写回时继续省略该字段。
259	type unsignedDoc struct {
260		Version     int            `json:"version"`
261		Initial     []BalanceView  `json:"initial_balances"`
262		Balances    []BalanceView  `json:"balances"`
263		Settlements []Record       `json:"settlements"`
264		Refunds     []RefundRecord `json:"refunds,omitempty"`
265	}
266	
267	type signedDoc struct {
268		unsignedDoc
269		Checksum string `json:"checksum"`
270	}
271	
272	func balanceList(m map[balanceKey]int64) []BalanceView {
273		out := make([]BalanceView, 0, len(m))
274		for k, v := range m {
275			out = append(out, BalanceView{Account: k.account, Asset: k.asset, Balance: v})
276		}
277		sortBalances(out)
278		return out
279	}
280	
281	func balanceMap(list []BalanceView) (map[balanceKey]int64, error) {
282		out := make(map[balanceKey]int64, len(list))
283		for i, b := range list {
284			if b.Account == "" || b.Asset == "" {
285				return nil, ledgerError(ErrCorrupt, "balance %d has empty account or asset", i)
286			}
287			if b.Balance < 0 {
288				return nil, ledgerError(ErrCorrupt, "negative balance for %s/%s", b.Account, b.Asset)
289			}
290			k := balanceKey{b.Account, b.Asset}
291			if _, dup := out[k]; dup {
292				return nil, ledgerError(ErrCorrupt, "duplicate balance entry for %s/%s", b.Account, b.Asset)
293			}
294			out[k] = b.Balance
295		}
296		return out, nil
297	}
298	
299	// MarshalJSON 输出带 sha256 校验和的单个 JSON 文档。
300	func (s *ledgerState) MarshalJSON() ([]byte, error) {
301		settlements := s.Settlements
302		if settlements == nil {
303			settlements = []Record{}
304		}
305		doc := unsignedDoc{
306			Version:     s.Version,
307			Initial:     balanceList(s.Initial),
308			Balances:    balanceList(s.Balances),
309			Settlements: settlements,
310			Refunds:     s.Refunds, // nil 时因 omitempty 省略，保持无退款账本的旧格式
311		}
312		payload, err := json.Marshal(doc)
313		if err != nil {
314			return nil, err
315		}
316		sum := checksumHex(payload)
317		out := make([]byte, 0, len(payload)+len(sum)+16)
318		out = append(out, payload[:len(payload)-1]...) // 去掉结尾 '}'
319		out = append(out, []byte(`,"checksum":"`+sum+`"}`)...)
320		return out, nil
321	}
322	
323	// UnmarshalJSON 校验 checksum、结构不变式并重放全部记录。
324	func (s *ledgerState) UnmarshalJSON(data []byte) error {
325		var doc signedDoc
326		if err := json.Unmarshal(data, &doc); err != nil {
327			return err
328		}
329		if doc.Checksum == "" {
330			return ledgerError(ErrCorrupt, "missing checksum")
331		}
332		payload, err := json.Marshal(doc.unsignedDoc)
333		if err != nil {
334			return ledgerError(ErrCorrupt, "re-encode ledger: %v", err)
335		}
336		if got := checksumHex(payload); got != doc.Checksum {
337			return ledgerError(ErrCorrupt, "checksum mismatch: file %s, want %s", doc.Checksum, got)
338		}
339		if doc.Version != ledgerVersion {
340			return ledgerError(ErrCorrupt, "unsupported ledger version %d", doc.Version)
341		}
342		initial, err := balanceMap(doc.Initial)
343		if err != nil {
344			return err
345		}
346		current, err := balanceMap(doc.Balances)
347		if err != nil {
348			return err
349		}
350		records := doc.Settlements
351		if records == nil {
352			records = []Record{}
353		}
354		refunds := doc.Refunds // 旧版账本缺省该字段，nil 视为空列表
355		if refunds == nil {
356			refunds = []RefundRecord{}
357		}
358		if err := validateAndReplay(initial, current, records, refunds); err != nil {
359			return err
360		}
361		s.Version = doc.Version
362		s.Initial = initial
363		s.Balances = current
364		s.Settlements = records
365		s.Refunds = refunds
366		return nil
367	}
368	
369	func decodeState(data []byte) (*ledgerState, error) {
370		var state ledgerState
371		if err := json.Unmarshal(data, &state); err != nil {
372			if le, ok := err.(*LedgerError); ok && le.Kind == ErrCorrupt {
373				return nil, err
374			}
375			return nil, ledgerError(ErrCorrupt, "parse ledger: %v", err)
376		}
377		return &state, nil
378	}
379	
380	// canonicalLedgerPath 把绝对路径解析为账本的规范路径：解析目录与文件本身
381	// 的符号链接，使同一账本经不同路径（如指向账本所在目录的软链接）打开时
382	// 共享同一注册表项、同一份内存状态与互斥锁。账本文件尚不存在时（未初始化）
383	// 解析其父目录；父目录也无法解析时退回原路径。
384	func canonicalLedgerPath(abs string) string {
385		if resolved, err := filepath.EvalSymlinks(abs); err == nil {
386			return resolved
387		}
388		if resolved, err := filepath.EvalSymlinks(filepath.Dir(abs)); err == nil {
389			return filepath.Join(resolved, filepath.Base(abs))
390		}
391		return abs
392	}
393	
394	// CreateLedger 在 path 处创建新账本。所有初始数据先校验，
395	// 任一不合法则返回 ErrInvalid 且不创建任何文件。
396	//
397	// “路径是否占用”与“创建账本”由内核一步原子完成（见 createExclusive）：
398	//   - 路径上已有正常账本、损坏或空的普通文件、目录：返回 ErrExists，
399	//     原内容逐字节不变；
400	//   - 账本文件位置上是符号链接时（无论链接指向文件还是目录、目标是否
401	//     存在）：返回 ErrExists，链接本身与其去向都不变，也不会顺着悬空
402	//     链接把目标文件创建出来；
403	//   - 经指向目录的符号链接访问一个尚未占用的文件位置时创建照常成功。
404	//
405	// 因此多个进程同时初始化同一尚不存在的账本（包括一方经真实目录、
406	// 另一方经指向该目录的符号链接访问同一目标）时，恰好一个成功，
407	// 其余返回 ErrExists，磁盘上完整保留胜出方的初始余额，绝不覆盖历史。
408	// 已有句柄打开（或有在途操作）的路径同样拒绝初始化。
409	func CreateLedger(path string, init []BalanceInit) error {
410		if err := validateInitial(init); err != nil {
411			return err
412		}
413		abs, err := filepath.Abs(path)
414		if err != nil {
415			return ledgerError(ErrStorage, "resolve path: %v", err)
416		}
417	
418		openMu.Lock()
419		defer openMu.Unlock()
420	
421		// 注册表按规范路径索引（父目录符号链接解析到真实目录），与 Open 一致。
422		// 注意 canonicalLedgerPath 对悬空符号链接只解析到其父目录、basename
423		// 仍是链接名；而下面的发布操作刻意使用字面 abs 而非该解析结果，确保
424		// 账本位置本身是符号链接时由内核原子拒绝，绝不顺着链接创建目标。
425		if openRegistry[canonicalLedgerPath(abs)] != nil {
426			// 已有句柄打开（或有在途操作）的路径不能再初始化：即便文件恰好被
427			// 外部删除，也不能用一本新账顶替正在使用的账本。
428			return ledgerError(ErrExists, "ledger is already initialized in this process")
429		}
430	
431		// 账本是否存在、内容是否完好一律以磁盘的原子创建结果为准；
432		// CreateLedger 不预登记内存状态，首次 Open 必须实际读取并校验该文件。
433		state := &ledgerState{
434			Version:     ledgerVersion,
435			Initial:     make(map[balanceKey]int64, len(init)),
436			Balances:    make(map[balanceKey]int64, len(init)),
437			Settlements: []Record{},
438			Refunds:     []RefundRecord{},
439		}
440		for _, b := range init {
441			k := balanceKey{b.Account, b.Asset}
442			state.Initial[k] = b.Balance
443			state.Balances[k] = b.Balance
444		}
445		// 发布使用字面绝对路径：父目录中的符号链接照常解析（允许经目录软链接
446		// 在尚未占用的文件位置创建新账本），账本位置本身的符号链接则被
447		// link(2) 原子拒绝；占用竞争失败返回 ErrExists，写入故障返回
448		// ErrStorage，两种情况下路径上都不会留下半成品。
449		if err := createExclusive(abs, state); err != nil {
450			return err
451		}
452		// 不登记 openRegistry：尚未有任何句柄，首次 Open 必须以磁盘文件为准，
453		// 这样在初始化与首次打开之间删除、清空或篡改文件都会被如实发现。
454		return nil
455	}
456	
457	func validateInitial(init []BalanceInit) error {
458		seen := map[balanceKey]bool{}
459		for i, b := range init {
460			if b.Account == "" {
461				return ledgerError(ErrInvalid, "initial balance %d: account must not be empty", i)
462			}
463			if b.Asset == "" {
464				return ledgerError(ErrInvalid, "initial balance %d: asset must not be empty", i)
465			}
466			if b.Balance < 0 {
467				return ledgerError(ErrInvalid, "initial balance %d (%s/%s): balance must be non-negative", i, b.Account, b.Asset)
468			}
469			k := balanceKey{b.Account, b.Asset}
470			if seen[k] {
471				return ledgerError(ErrInvalid, "initial balance %d: duplicate entry for %s/%s", i, b.Account, b.Asset)
472			}
473			seen[k] = true
474		}
475		return nil
476	}
477	
478	// Ledger 是一个可持久化的本地账本。同一进程内指向同一账本文件的多次 Open
479	// （包括经目录软链接的不同路径）返回共享同一状态与互斥锁的实例，
480	// 因此并发提交按同一本账本串行化。
481	type Ledger struct {
482		path string
483		reg  *registryEntry
484		open bool
485	}
486	
487	type registryEntry struct {
488		mu       sync.Mutex // 保护 state；整个批次串行持有
489		state    *ledgerState
490		holders  map[*Ledger]struct{} // 当前打开的句柄
491		ops      int                  // 正在执行的 Submit/Query 数（含已关闭句柄的在途操作）
492		failHook FailWriter           // 仅测试注入
493	}
494	
495	// alive 报告该注册表项是否仍须保留：至少还有一个打开的句柄，或一个
496	// （可能来自已关闭句柄的）在途操作。全为零时该项可被注销，此后的 Open
497	// 重新以磁盘文件为准。
498	// 调用方必须持有 openMu。
499	func (r *registryEntry) alive() bool {
500		return len(r.holders) > 0 || r.ops > 0
501	}
502	
503	// tryEvict 仅在没有句柄且没有在途操作时注销注册表项。
504	// 调用方必须持有 openMu。
505	func tryEvict(path string, reg *registryEntry) {
506		if !reg.alive() && openRegistry[path] == reg {
507			delete(openRegistry, path)
508		}
509	}
510	
511	var (
512		openMu       sync.Mutex
513		openRegistry = map[string]*registryEntry{}
514	)
515	
516	// Open 打开（或复用）path 处的账本。账本必须已由 CreateLedger 初始化；
517	// 文件缺失返回 ErrNotInit，内容损坏返回 ErrCorrupt，不会被当成空账本重来。
518	func Open(path string) (*Ledger, error) {
519		abs, err := filepath.Abs(path)
520		if err != nil {
521			return nil, ledgerError(ErrStorage, "resolve path: %v", err)
522		}
523		abs = canonicalLedgerPath(abs)
524	
525		openMu.Lock()
526		defer openMu.Unlock()
527	
528		if reg := openRegistry[abs]; reg != nil {
529			// 同进程已有句柄（或在途操作）承接该账本：共享当前完整状态，不重新读盘。
530			// 注册表项只在存在活动句柄/在途操作期间保留，因此走到这里时磁盘文件
531			// 的状态已不再权威——例如它可能正被一笔在途付款以原子写替换。
532			h := &Ledger{path: abs, reg: reg, open: true}
533			reg.holders[h] = struct{}{}
534			return h, nil
535		}
536	
537		data, err := os.ReadFile(abs)
538		if err != nil {
539			if errors.Is(err, os.ErrNotExist) {
540				return nil, ledgerError(ErrNotInit, "no ledger at %s; initialize it first", abs)
541			}
542			return nil, ledgerError(ErrStorage, "read %s: %v", abs, err)
543		}
544		if len(bytes.TrimSpace(data)) == 0 {
545			return nil, ledgerError(ErrCorrupt, "ledger file %s is empty", abs)
546		}
547		dec := json.NewDecoder(bytes.NewReader(data))
548		var rawDoc json.RawMessage
549		if err := dec.Decode(&rawDoc); err != nil {
550			return nil, ledgerError(ErrCorrupt, "parse %s: %v", abs, err)
551		}
552		// 不允许尾随内容：防止文件被拼接/截断后被误读为合法。
553		if tok, err := dec.Token(); err != io.EOF {
554			if err == nil {
555				return nil, ledgerError(ErrCorrupt, "unexpected trailing data after ledger document (token %v)", tok)
556			}
557			return nil, ledgerError(ErrCorrupt, "trailing data after ledger document: %v", err)
558		}
559		state, err := decodeState(rawDoc)
560		if err != nil {
561			return nil, err
562		}
563	
564		reg := &registryEntry{state: state, holders: map[*Ledger]struct{}{}}
565		h := &Ledger{path: abs, reg: reg, open: true}
566		reg.holders[h] = struct{}{}
567		openRegistry[abs] = reg
568		return h, nil
569	}
570	
571	// Close 释放句柄；同一进程可再次 Open 同一文件并继续使用。
572	// 若关闭时有在途提交，注册表项保留到在途操作结束，避免并发 Open
573	// 从磁盘重新加载而丢失正在写入的状态。
574	func (l *Ledger) Close() error {
575		openMu.Lock()
576		defer openMu.Unlock()
577		if !l.open {
578			return nil
579		}
580		l.open = false
581		delete(l.reg.holders, l)
582		tryEvict(l.path, l.reg)
583		return nil
584	}
585	
586	// beginOp 标记一次在途操作。返回 nil 表示句柄已关闭。
587	func (l *Ledger) beginOp() error {
588		openMu.Lock()
589		defer openMu.Unlock()
590		if !l.open {
591			return ledgerError(ErrClosed, "ledger handle is closed")
592		}
593		l.reg.ops++
594		return nil
595	}
596	
597	func (l *Ledger) endOp() {
598		openMu.Lock()
599		defer openMu.Unlock()
600		l.reg.ops--
601		tryEvict(l.path, l.reg)
602	}
603	
604	// feeFor 计算手续费：amount*feeBps/10000 向下取整。
605	// amount>0、0<=feeBps<=10000 时朴素乘积可能溢出 int64，
606	// 拆成商和余数两部分即可在 int64 内精确完成。
607	func feeFor(amount int64, feeBps int) int64 {
608		hi := amount / 10000
609		lo := amount % 10000
610		return hi*int64(feeBps) + (lo*int64(feeBps))/10000
611	}
612	
613	func validateIntent(it PaymentIntent) (int64, string, bool) {
614		if it.ID == "" {
615			return 0, reasonEmptyID, false
616		}
617		if it.Account == "" {
618			return 0, reasonEmptyAccount, false
619		}
620		if it.Asset == "" {
621			return 0, reasonEmptyAsset, false
622		}
623		if it.Amount == nil || *it.Amount <= 0 {
624			return 0, reasonBadAmount, false
625		}
626		return *it.Amount, "", true
627	}
628	
629	// validateLimits 校验本次提交的扣款上限：账户与资产必须非空，同一组合不得重复，
630	// max_charged 必须明确提供且为非负 int64。任一不合法则整个批次拒绝（ErrInvalid），
631	// 与意图列表是否为空无关。合法时返回按组合索引的上限表；无上限时返回 nil。
632	func validateLimits(limits []ChargeLimit) (map[balanceKey]int64, error) {
633		if len(limits) == 0 {
634			return nil, nil
635		}
636		out := make(map[balanceKey]int64, len(limits))
637		for i, l := range limits {
638			if l.Account == "" {
639				return nil, ledgerError(ErrInvalid, "limit %d: account must not be empty", i)
640			}
641			if l.Asset == "" {
642				return nil, ledgerError(ErrInvalid, "limit %d: asset must not be empty", i)
643			}
644			if l.MaxCharged == nil {
645				return nil, ledgerError(ErrInvalid, "limit %d (%s/%s): max_charged must be provided", i, l.Account, l.Asset)
646			}
647			if *l.MaxCharged < 0 {
648				return nil, ledgerError(ErrInvalid, "limit %d (%s/%s): max_charged must be non-negative, got %d", i, l.Account, l.Asset, *l.MaxCharged)
649			}
650			k := balanceKey{l.Account, l.Asset}
651			if _, dup := out[k]; dup {
652				return nil, ledgerError(ErrInvalid, "limit %d: duplicate entry for %s/%s", i, l.Account, l.Asset)
653			}
654			out[k] = *l.MaxCharged
655		}
656		return out, nil
657	}
658	
659	// Submit 按输入顺序结算一个批次。各项独立成功或失败：后项看到前项
660	// 成功后的余额；任一项失败不影响其余项（存储错误只回滚出错项本身，
661	// 已完成的前项不回滚）。结果与输入逐项对应，空批次返回空结果。
662	//
663	// 若批次携带 limits，则每个列出的 (账户, 资产) 组合在本次提交内的成功扣款
664	// 累计（含手续费）不得超过其 max_charged：超限的项返回 limit_exceeded，
665	// 不扣余额、不留记录、不占编号与额度；未列出的组合不限制。额度按本次提交
666	// 从零计算，只有成功落账的扣款消耗额度，历史扣款与退款均不计入。
667	func (l *Ledger) Submit(batch FeeBatch) (*BatchResult, error) {
668		if err := l.beginOp(); err != nil {
669			return nil, err
670		}
671		defer l.endOp()
672		limits, err := validateBatch(batch)
673		if err != nil {
674			return nil, err
675		}
676	
677		l.reg.mu.Lock()
678		defer l.reg.mu.Unlock()
679	
680		results := runBatch(batch, limits, l.reg.state, l.persistEffect)
681		return &BatchResult{Results: results}, nil
682	}
683	
684	// Preview 在不写入账本的前提下，按当前账本预计算一个批次的结算结果，
685	// 语义与 Submit 逐项一致（状态、失败原因、结算记录格式均相同）：
686	//   - 后项看到前项“预计成功”后的可用余额与本批次已用限额；
687	//   - 预计成功的新付款使用从当前最大付款序号之后连续递增的序号，
688	//     失败、重复、冲突不消耗序号；
689	//   - 已有成功编号仍按原付款字段与费率判断重复或冲突（原付款已退款也一样），
690	//     重复项携带原记录，不占余额与本批次额度；本批次首次预计成功的编号对
691	//     后续项同样生效（相同请求重复、字段不同冲突），失败项不占编号；
692	//   - 手续费、金额溢出、状态与限额判断沿用实际提交规则，同时超限与余额不足
693	//     仍先报告超限，限额只累计本次预计成功的扣款（含手续费）。
694	//
695	// 预览全程在当前状态的深拷贝上进行：不持久化、不修改真实余额与历史，
696	// 任何编号、序号和额度都不被预留；连续预览相同批次（账本未变化）结果一致，
697	// 随后真实提交仍按首次提交处理。预览只预测业务结果，不承诺真实提交时的
698	// 写入成功（因此预览结果中不会出现 storage_error）。费率或限额非法属于
699	// 批次级错误，返回 invalid_parameter 且不产生部分结果（空批次同样检查）。
700	func (l *Ledger) Preview(batch FeeBatch) (*PreviewResult, error) {
701		if err := l.beginOp(); err != nil {
702			return nil, err
703		}
704		defer l.endOp()
705		limits, err := validateBatch(batch)
706		if err != nil {
707			return nil, err
708		}
709	
710		l.reg.mu.Lock()
711		defer l.reg.mu.Unlock()
712	
713		// 在快照副本上模拟：预览结束后真实状态与磁盘文件保持原样。
714		sim := cloneState(l.reg.state)
715		results := runBatch(batch, limits, sim, simulateEffect)
716		return &PreviewResult{DryRun: true, Results: results}, nil
717	}
718	
719	// validateBatch 执行批次级校验：费率范围与本次扣款上限。任一不合法都返回
720	// 批次级错误（invalid_parameter），调用方不得执行任何意图（空批次同样检查）。
721	func validateBatch(batch FeeBatch) (map[balanceKey]int64, error) {
722		if batch.FeeBps < 0 || batch.FeeBps > 10000 {
723			return nil, ledgerError(ErrInvalid, "fee_bps must be within [0,10000], got %d", batch.FeeBps)
724		}
725		// 限额非法是批次级错误：任何意图都不执行（空意图列表同样检查）。
726		return validateLimits(batch.Limits)
727	}
728	
729	// ledgerEffect 是一笔预计成功落账（付款扣款或退款退回）的全部账本效果：
730	// 变动哪个组合、余额增减多少、向哪一类成功历史追加什么记录。delta 为正
731	// 表示增加余额（退款），为负表示减少余额（付款扣款）。它由各自的业务规则
732	// 产生，本身尚未生效；是否生效、如何生效（真实落盘或预览模拟）由生效策略
733	// 决定。付款与退款共用这一个效果结构，因此“改余额 + 追加成功记录 +
734	// 保存失败恢复原状”的落账步骤只需在 applyEffect 一处维护。
735	type ledgerEffect struct {
736		key      balanceKey
737		delta    int64
738		settling *Record       // 付款成功时追加到结算历史；退款时为 nil
739		refund   *RefundRecord // 退款成功时追加到退款历史；付款时为 nil
740	}
741	
742	// applyEffect 把一笔预计成功的落账效果应用到状态 st：余额变动与对应成功
743	// 记录在同一步完成，查询不会看到只有余额变化而没有记录的状态。返回回滚
744	// 函数，恢复该项执行前的余额与对应历史长度（只撤销该项自己的变化，
745	// 不动另一类历史、不动之前已成功的记录）。付款与退款的落账与回滚都走
746	// 这一个出口。
747	func applyEffect(st *ledgerState, eff ledgerEffect) func() {
748		oldBal, hadKey := st.Balances[eff.key]
749		st.Balances[eff.key] = oldBal + eff.delta
750	
751		var oldSettlements, oldRefunds int
752		if eff.settling != nil {
753			oldSettlements = len(st.Settlements)
754			st.Settlements = append(st.Settlements, *eff.settling)
755		} else {
756			oldRefunds = len(st.Refunds)
757			st.Refunds = append(st.Refunds, *eff.refund)
758		}
759	
760		return func() {
761			if hadKey {
762				st.Balances[eff.key] = oldBal
763			} else {
764				delete(st.Balances, eff.key)
765			}
766			if eff.settling != nil {
767				st.Settlements = st.Settlements[:oldSettlements]
768			} else {
769				st.Refunds = st.Refunds[:oldRefunds]
770			}
771		}
772	}
773	
774	// commitEffect 是落账生效策略：把一笔预计成功的效果应用到状态 st 上。
775	// 返回 nil 表示已生效；返回非 nil 表示保存失败，且 st 必须已恢复到
776	// 该项执行之前的余额与历史。
777	type commitEffect func(st *ledgerState, eff ledgerEffect) error
778	
779	// runBatch 按输入顺序在给定状态 st 上处理整个批次，返回逐项结果。
780	// 付款规则（judgeIntent）与落账生效（commit）分离：规则只读取 st 与
781	// 本批次已用额度给出判定和预计落账效果，不改动任何状态；生效策略决定
782	// 效果如何落地——真实提交先改内存再原子落盘、失败回滚并报告
783	// storage_error，预览只在副本上推进内存状态、绝不落盘。两种操作共用
784	// 同一份规则，因此逐项判定完全一致。调用方必须持有 reg.mu。
785	func runBatch(batch FeeBatch, limits map[balanceKey]int64, st *ledgerState, commit commitEffect) []ItemResult {
786		out := make([]ItemResult, 0, len(batch.Intents))
787	
788		// 本次批次内各组合已消耗的额度，从零开始，仅成功生效的扣款计入。
789		used := make(map[balanceKey]int64, len(limits))
790	
791		for i := range batch.Intents {
792			it := &batch.Intents[i]
793	
794			// 1. 规则判定：纯读取，不产生任何副作用。
795			res, eff := judgeIntent(it, batch.FeeBps, limits, used, st)
796			if eff == nil {
797				out = append(out, res)
798				continue
799			}
800	
801			// 2. 生效：保存失败时 commit 已回滚该项（余额与历史恢复原样），
802			//    该项报告 storage_error，不留记录、不占额度，后项继续处理。
803			if err := commit(st, *eff); err != nil {
804				res.Status = StatusStorage
805				res.Reason = err.Error()
806				out = append(out, res)
807				continue
808			}
809	
810			// 3. 只有成功生效的扣款才消耗本批次额度（预览同样如此）。
811			used[eff.key] += -eff.delta
812			cp := *eff.settling
813			res.Status = StatusSettled
814			res.Record = &cp
815			out = append(out, res)
816		}
817		return out
818	}
819	
820	// judgeIntent 按付款规则评估一项请求，只读取状态与额度用量，不产生副作用。
821	// 返回逐项结果；预计成功时结果只填编号，落账效果以 ledgerEffect 描述，
822	// 由调用方交给生效策略落地。判定顺序即对外约定：参数校验、已成功编号的
823	// 重复/冲突、状态、溢出、本批次限额（先于余额）、余额。
824	func judgeIntent(it *PaymentIntent, feeBps int, limits map[balanceKey]int64, used map[balanceKey]int64, st *ledgerState) (ItemResult, *ledgerEffect) {
825		res := ItemResult{ID: it.ID}
826	
827		// 1. 参数校验。未通过的编号不占用去重资格。
828		amount, reason, ok := validateIntent(*it)
829		if !ok {
830			res.Status = StatusInvalid
831			res.Reason = reason
832			return res, nil
833		}
834	
835		// 2. 已成功编号：字段与费率完全一致则幂等返回原记录；
836		//    任一不同则编号冲突。两者都不再扣款、不改原记录。
837		//    本批次内先（预计）成功的同编号项也在此被看到。
838		if rec, exists := findRecordIn(st.Settlements, it.ID); exists {
839			if sameRequest(rec, it, amount, feeBps) {
840				cp := rec
841				res.Status = StatusDuplicate
842				res.Reason = reasonDuplicate
843				res.Record = &cp
844			} else {
845				res.Status = StatusConflict
846				res.Reason = reasonConflict
847			}
848			return res, nil
849		}
850	
851		// 3. 状态错误单独报告（不占用去重资格，之后可重新提交）。
852		if it.State != "" && it.State != "pending" {
853			res.Status = StatusState
854			res.Reason = reasonNotPending
855			return res, nil
856		}
857	
858		// 4. 手续费与扣款总额（溢出明确按参数错误拒绝）。
859		fee := feeFor(amount, feeBps)
860		if fee > math.MaxInt64-amount {
861			res.Status = StatusInvalid
862			res.Reason = reasonOverflow
863			return res, nil
864		}
865		total := amount + fee
866	
867		key := balanceKey{it.Account, it.Asset}
868	
869		// 5. 本次批次限额（先于余额判断：同时超限与余额不足时报告超限）。
870		//    恰好达到上限仍允许；用 total > max-used 而非 used+total > max，
871		//    避免累计接近 int64 上界时溢出放行。失败不消耗额度。
872		if max, capped := limits[key]; capped {
873			if u := used[key]; total > max-u {
874				res.Status = StatusLimitExceeded
875				res.Reason = fmt.Sprintf(reasonLimitExceeded, it.Account, it.Asset, max, u, total)
876				return res, nil
877			}
878		}
879	
880		// 6. 余额校验。不存在的账户/资产组合余额视为 0（不足）。
881		if total > st.Balances[key] {
882			res.Status = StatusFunds
883			res.Reason = reasonFunds
884			return res, nil
885		}
886	
887		// 7. 预计成功：描述落账效果（余额扣减总额、序号按当前结算历史长度
888		//    连续递增）。
889		rec := Record{
890			ID:        it.ID,
891			Account:   it.Account,
892			Paymaster: it.Paymaster,
893			Asset:     it.Asset,
894			Amount:    amount,
895			Nonce:     it.Nonce,
896			FeeBps:    feeBps,
897			Fee:       fee,
898			Charged:   total,
899			Seq:       int64(len(st.Settlements)) + 1,
900		}
901		return res, &ledgerEffect{
902			key:      key,
903			delta:    -total,
904			settling: &rec,
905		}
906	}
907	
908	// simulateEffect 是预览的生效策略：只在（副本）状态上推进余额与对应
909	// 历史，绝不触碰磁盘，因此不会失败，预览结果中也不会出现 storage_error。
910	func simulateEffect(st *ledgerState, eff ledgerEffect) error {
911		applyEffect(st, eff)
912		return nil
913	}
914	
915	// persistEffect 是真实落账（付款与退款共用）的生效策略：先在内存生效
916	// （余额变动与成功记录同一步完成），再原子落盘；落盘失败回滚该项
917	// （applyEffect 返回的回滚恢复余额与对应历史），并返回存储错误。
918	func (l *Ledger) persistEffect(st *ledgerState, eff ledgerEffect) error {
919		rollback := applyEffect(st, eff)
920		if err := l.persistLocked(); err != nil {
921			rollback()
922			return err
923		}
924		return nil
925	}
