945	// findRecordIn 在给定结算历史中按编号查找成功记录。
946	func findRecordIn(records []Record, id string) (Record, bool) {
947		// 记录按成功顺序追加且 ID 唯一；单机账本量级直接扫描。
948		for _, r := range records {
949			if r.ID == id {
950				return r, true
951			}
952		}
953		return Record{}, false
954	}
