1136	// sameRequest 比较全部付款字段与费率。付款字段：账户、付款方、资产、金额、nonce。
1137	func sameRequest(r Record, it *PaymentIntent, amount int64, feeBps int) bool {
1138		return r.Account == it.Account &&
1139			r.Paymaster == it.Paymaster &&
1140			r.Asset == it.Asset &&
1141			r.Amount == amount &&
1142			r.Nonce == it.Nonce &&
1143			r.FeeBps == feeBps
1144	}
