type failOnce struct{ remaining int }

func (f *failOnce) FailNextPersist() bool {
	if f.remaining > 0 {
		f.remaining--
		return true
	}
	return false
}

// failNth 在第 nth 次（1 起）持久化时失败，其余成功。
type failNth struct {
	nth   int
	calls int
}

